UPDATE CBCI_INTERPARK_SALES 
SET EXACT_SETTLE_DATE = #{EXACT_DATE_VAL}
WHERE ORDER_NO = #{ORDER_NO}
AND PRODUCT_NO = #{PRODUCT_NO}
AND OPTION_NAME = #{OPTION_NAME}

UPDATE CBCI_GMARKET_SALES 
SET EXACT_SETTLE_DATE = #{EXACT_DATE_VAL}
WHERE ORDER_NO = #{ORDER_NO}
AND PRODUCT_NO = #{PRODUCT_NO}

UPDATE CBCI_AUCTION_SALES
SET EXACT_SETTLE_DATE = #{EXACT_DATE_VAL}
