UPDATE CBCI_11ST_SALEACCNT
SET EXACT_SETTLE_DATE = #{EXACT_DATE_VAL}
WHERE 주문번호 = #{ORDER_NO}
AND 주문순번 = #{ORDER_TURN}
AND 선결제배송비 = #{PAYDEL_AMOUNT}
AND 반품보험료 = #{RETURN_INSUR};

UPDATE CBCI_NAVER_SALES
SET EXACT_SETTLE_DATE = #{EXACT_DATE_VAL}
